'use client';
import { Fragment, useEffect, useLayoutEffect, useRef, useState, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useReducedMotion } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { avatarInk, enter, Fold, Spin, useMounted, useReflow } from '../lib/motion';
import { useColumns } from '../lib/columns';

type AccountCol = 'account' | 'plan' | 'seats' | 'health' | 'mrr';
const COLS: { key: AccountCol; label: string; right?: boolean }[] = [
  { key: 'account', label: 'Account' }, { key: 'plan', label: 'Plan' }, { key: 'seats', label: 'Seats', right: true }, { key: 'health', label: 'Health' }, { key: 'mrr', label: 'MRR', right: true }
];
import '../designme.css';
import './account-table.css';

/** The tag colours a plan can take */
export type AccountTableTone = 'blue' | 'purple' | 'green' | 'orange' | 'red' | 'yellow' | 'pink' | 'teal';

export interface AccountTableAccount {
  /** Also the account's key, and its first letter makes the logo */
  name: string;
  /** The logo's colour, like 'var(--dm-av-b)'. An avatar colour brings its own ink for the letter, any other colour takes white */
  color: string;
  plan: string;
  seats: number;
  /** 0 to 100. Green from 80, amber from 60, red below */
  health: number;
  /** Already formatted, like "$14,400" */
  mrr: string;
  /** What the agent noticed, shown when the row opens */
  note?: ReactNode;
}

export interface AccountTableProps {
  accounts: AccountTableAccount[];
  /** The plan filters after All. Defaults to the plans in `accounts`, in the order they first appear */
  plans?: string[];
  /** The tag colour for each plan. Defaults to Enterprise purple, Pro blue, Team teal */
  planTones?: Record<string, AccountTableTone>;
  /** The plan filter, or '' for All */
  plan?: string;
  defaultPlan?: string;
  onPlanChange?: (plan: string) => void;
  /** The search text. Matches account names */
  query?: string;
  defaultQuery?: string;
  onQueryChange?: (query: string) => void;
  /** The account whose row is open, or null */
  open?: string | null;
  defaultOpen?: string | null;
  onOpenChange?: (name: string | null) => void;
  /** A button in the open row's note, like Draft email. Return a promise and it says `busyLabel` with a spinner until it
      settles, then `doneLabel` with a green tick. The button is as wide as its words and eases to each new width */
  action?: { label: string; busyLabel?: string; doneLabel?: string; onClick: (account: AccountTableAccount) => void | Promise<unknown> };
  placeholder?: string;
  /** The title of the empty state, when nothing matches the search and filter */
  emptyLabel?: string;
  /** The muted line under it */
  emptyHint?: string;
  /** Its button, which clears the search and the plan filter */
  clearLabel?: string;
  className?: string;
}

const TONE: Record<AccountTableTone, string> = { blue: 'dm-b', purple: 'dm-l', green: 'dm-m', orange: 'dm-p', red: 'dm-r', yellow: 'dm-y', pink: 'dm-k', teal: 'dm-t' };
const TONES: Record<string, AccountTableTone> = { Enterprise: 'purple', Pro: 'blue', Team: 'teal' };
const healthColor = (h: number) => h >= 80 ? 'var(--dm-atb-ok)' : h >= 60 ? 'var(--dm-atb-warn)' : 'var(--dm-atb-bad)';

/** Accounts you can search and filter by plan; a row opens to show what the agent noticed. */
export function AccountTable({
  accounts, plans, planTones = TONES, plan, defaultPlan = '', onPlanChange, query, defaultQuery = '', onQueryChange,
  open, defaultOpen = null, onOpenChange, action, placeholder = 'Search accounts', emptyLabel = 'No accounts match',
  emptyHint = 'Try another name, or show every plan.', clearLabel = 'Show all accounts', className
}: AccountTableProps) {
  const [filter, setFilter] = useControllable(plan, defaultPlan, onPlanChange);
  const [text, setText] = useControllable(query, defaultQuery, onQueryChange);
  const [opened, setOpened] = useControllable(open, defaultOpen, onOpenChange);
  const tabs = plans ?? [...new Set(accounts.map(a => a.plan))];
  const s = text.trim().toLowerCase();
  const rows = accounts.filter(a => (!filter || a.plan === filter) && (!s || a.name.toLowerCase().includes(s)));

  // the rows stagger in once; after that a search or a plan filter glides the rows that still match to their new places,
  // fades new ones in and fades the ones filtered out where they were
  const box = useRef<HTMLDivElement>(null);
  useReflow(box, 'tbody > tr[data-key]');
  const mounted = useMounted();

  // an open row's note opens by its height and the rows under it ease down; it folds shut the same way, and goes once folded
  const [shut, setShut] = useState<string | null>(null);
  const [was, setWas] = useState(opened);
  if (was !== opened) { setWas(opened); if (was) setShut(was); }

  // the action button resets whenever another row opens
  const [draft, setDraft] = useState<'idle' | 'busy' | 'done'>('idle');
  const [draftFor, setDraftFor] = useState(opened);
  if (draftFor !== opened) { setDraftFor(opened); setDraft('idle'); }
  const alive = useRef(true);
  useEffect(() => { alive.current = true; return () => { alive.current = false; }; }, []);
  const run = (a: AccountTableAccount) => {
    if (!action || draft === 'busy') return;
    const r = action.onClick(a);
    if (r && typeof (r as Promise<unknown>).then === 'function') {
      setDraft('busy');
      (r as Promise<unknown>).then(() => { if (alive.current) setDraft('done'); }, () => { if (alive.current) setDraft('idle'); });
    } else setDraft('done');
  };

  const toggle = (name: string) => setOpened(opened === name ? null : name);

  // the columns resize and move as in a spreadsheet; Account stays first, and every other header takes the keyboard's focus,
  // so Alt and an arrow move it
  const cols = useColumns<AccountCol>(COLS.map(c => c.key), { move: ['plan', 'seats', 'health', 'mrr'], min: { account: 150, plan: 96, seats: 72, health: 112, mrr: 88 }, name: k => COLS.find(c => c.key === k)!.label });
  const cell = (a: AccountTableAccount, k: AccountCol): ReactNode => {
    const tone = planTones[a.plan];
    switch (k) {
      case 'account': return <td key={k} data-col={k}><span className="dm-nm"><span className="dm-lg" style={{ background: a.color, color: avatarInk(a.color) }}>{a.name[0]}</span>{a.name}</span></td>;
      case 'plan': return <td key={k} data-col={k}><span className={cx('dm-tag', tone && TONE[tone])}>{a.plan}</span></td>;
      case 'seats': return <td key={k} data-col={k} className="dm-r dm-num">{a.seats}</td>;
      case 'health': return <td key={k} data-col={k}><span className="dm-hb"><i><b style={{ width: a.health + '%', background: healthColor(a.health) }} /></i><span className="dm-num">{a.health}</span></span></td>;
      default: return <td key={k} data-col={k} className="dm-r dm-num">{a.mrr}</td>;
    }
  };

  return (
    <div data-dm="" ref={box} className={cx('dm-atb dm-panel', className)}>
      <div className="dm-atb-h">
        <label className="dm-atb-s"><Icon name="search" size="xs" /><input placeholder={placeholder} aria-label={placeholder} value={text} onChange={e => setText(e.target.value)} /></label>
        <div className="dm-atb-fl" role="group" aria-label="Plan">
          {['', ...tabs].map(p => (
            <button type="button" key={p || 'all'} className={cx('dm-chip dm-sm', filter === p && 'dm-on')} aria-pressed={filter === p} onClick={() => setFilter(p)}>{p || 'All'}</button>
          ))}
        </div>
      </div>
      <div className="dm-atb-sc">
        <table {...cols.table} className={cx(cols.sized && 'dm-cols-rz')}>
          {cols.colgroup}
          <thead><tr>{cols.order.map(k => { const c = COLS.find(x => x.key === k)!; return <th key={k} {...cols.head(k)} className={c.right ? 'dm-r' : undefined} tabIndex={k === 'account' ? undefined : 0}>{c.label}{cols.handle(k)}</th>; })}</tr></thead>
          <tbody>
            {rows.length ? rows.map((a, i) => {
              const isOpen = opened === a.name, e = mounted ? undefined : enter(i * 35);
              return (
                <Fragment key={a.name}>
                  <tr data-key={a.name} className={cx('dm-row', isOpen && 'dm-open', e?.className)} style={e?.style} tabIndex={0} aria-expanded={isOpen}
                    onClick={() => toggle(a.name)} onKeyDown={e => { if ((e.key === 'Enter' || e.key === ' ') && e.target === e.currentTarget) { e.preventDefault(); toggle(a.name); } }}>
                    {cols.order.map(k => cell(a, k))}
                  </tr>
                  {(isOpen || shut === a.name) && (
                    <Note name={a.name} open={isOpen} onGone={() => setShut(x => x === a.name ? null : x)}>
                          <div className="dm-atb-note dm-enter">
                            <Icon name="spark" size="xs" />
                            <span>{a.note}</span>
                            {action && <ActionButton state={draft} action={action} onClick={() => run(a)} />}
                          </div>
                    </Note>
                  )}
                </Fragment>
              );
            }) : <tr className="dm-atb-empty" data-key=" none"><td colSpan={5}><div className="dm-atb-em">
              <span className="dm-atb-em-art" aria-hidden="true" /><b>{emptyLabel}</b>{emptyHint && <span>{emptyHint}</span>}
              <button type="button" className="dm-pill dm-line dm-sm" onClick={() => { setText(''); setFilter(''); }}>{clearLabel}</button>
            </div></td></tr>}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/** The note's button: its words, then a spinner with the busy words in the loader's sweep, then the green tick with the done
    words. It is always as wide as its words and eases to each new width, so it never jumps or goes blank */
function ActionButton({ state, action, onClick }: { state: 'idle' | 'busy' | 'done'; action: NonNullable<AccountTableProps['action']>; onClick: () => void }) {
  const ref = useRef<HTMLButtonElement>(null), was = useRef<number | null>(null);
  const reduce = useReducedMotion();
  // the width it had before this state's words went in, read before the browser paints them
  const w0 = was.current;
  useLayoutEffect(() => {
    const b = ref.current; if (!b) return; const w1 = b.getBoundingClientRect().width; was.current = w1;
    if (reduce || w0 === null || Math.abs(w1 - w0) < .5 || !b.animate) return;
    const cs = getComputedStyle(b);
    b.animate([{ width: w0 + 'px' }, { width: w1 + 'px' }], { duration: (parseFloat(cs.getPropertyValue('--dm-t')) || .45) * 1000, easing: cs.getPropertyValue('--dm-ease').trim() || 'ease' });
  }, [state]); // eslint-disable-line react-hooks/exhaustive-deps
  return (
    <button ref={ref} type="button" className="dm-pill dm-line dm-sm" aria-busy={state === 'busy'} onClick={e => { e.stopPropagation(); onClick(); }}>
      {state === 'busy' ? <><Spin /><span className="dm-shim">{action.busyLabel ?? 'Working'}</span></>
        : state === 'done' ? <><span className="dm-atb-done"><Icon name="check" size="xs" /></span>{action.doneLabel ?? 'Done'}</> : action.label}
    </button>
  );
}

/** The note under an open row: it mounts shut and folds open on the next frame; told to close, it folds shut and then goes */
function Note({ name, open, onGone, children }: { name: string; open: boolean; onGone: () => void; children: ReactNode }) {
  const [on, setOn] = useState(false);
  const reduce = useReducedMotion();
  const ref = useRef<HTMLTableRowElement>(null);
  useEffect(() => {
    if (open) { const f = requestAnimationFrame(() => setOn(true)); return () => cancelAnimationFrame(f); }
    setOn(false);
    const ms = reduce || !ref.current ? 0 : (parseFloat(getComputedStyle(ref.current).getPropertyValue('--dm-t')) || .45) * 1000;
    const t = setTimeout(onGone, ms); return () => clearTimeout(t);
  }, [open]); // eslint-disable-line react-hooks/exhaustive-deps
  return (
    <tr ref={ref} className="dm-det" data-key={name + ' note'}>
      <td colSpan={5}><Fold open={on}>{children}</Fold></td>
    </tr>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Account table ---------- */
/* the account table's colours run brighter than the shared tones: its plan tags take a stronger tint with saturated text
   (4.5:1 and APCA Lc 60 on the tint, in every style and theme) and the health bars vivid marks (3:1) */
.dm-atb{--dm-atb-ok:#1daa51;--dm-atb-warn:#cd7a00;--dm-atb-bad:#f04438;
  --dm-pb:#0663d2;--dm-pb-bg:color-mix(in srgb,#4890fa 15%,transparent);--dm-pl:#7d2dfc;--dm-pl-bg:color-mix(in srgb,#9776fa 15%,transparent);--dm-pm:#087744;--dm-pm-bg:color-mix(in srgb,#1fad66 15%,transparent);--dm-pp:#a34f06;--dm-pp-bg:color-mix(in srgb,#dc7019 15%,transparent);
  --dm-pr:#c50b2d;--dm-pr-bg:color-mix(in srgb,#fb4652 15%,transparent);--dm-py:#886006;--dm-py-bg:color-mix(in srgb,#bb881a 15%,transparent);--dm-pk:#b80a75;--dm-pk-bg:color-mix(in srgb,#fb27a2 15%,transparent);--dm-pt:#08727c;--dm-pt-bg:color-mix(in srgb,#1fa5b1 15%,transparent)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .dm-atb{--dm-atb-ok:#5fcb2a;--dm-atb-warn:#f59e0b;--dm-atb-bad:#fb4849;
  --dm-pb:#a4c9fe;--dm-pb-bg:color-mix(in srgb,#4890fa 22%,transparent);--dm-pl:#c9befe;--dm-pl-bg:color-mix(in srgb,#9776fa 22%,transparent);--dm-pm:#19e285;--dm-pm-bg:color-mix(in srgb,#1fad66 22%,transparent);--dm-pp:#feb68b;--dm-pp-bg:color-mix(in srgb,#dc7019 22%,transparent);
  --dm-pr:#feb1ad;--dm-pr-bg:color-mix(in srgb,#fb4652 22%,transparent);--dm-py:#feba28;--dm-py-bg:color-mix(in srgb,#bb881a 22%,transparent);--dm-pk:#feabcf;--dm-pk-bg:color-mix(in srgb,#fb27a2 22%,transparent);--dm-pt:#19daeb;--dm-pt-bg:color-mix(in srgb,#1fa5b1 22%,transparent)}}
:root[data-theme="dark"] .dm-atb{--dm-atb-ok:#5fcb2a;--dm-atb-warn:#f59e0b;--dm-atb-bad:#fb4849;
  --dm-pb:#a4c9fe;--dm-pb-bg:color-mix(in srgb,#4890fa 22%,transparent);--dm-pl:#c9befe;--dm-pl-bg:color-mix(in srgb,#9776fa 22%,transparent);--dm-pm:#19e285;--dm-pm-bg:color-mix(in srgb,#1fad66 22%,transparent);--dm-pp:#feb68b;--dm-pp-bg:color-mix(in srgb,#dc7019 22%,transparent);
  --dm-pr:#feb1ad;--dm-pr-bg:color-mix(in srgb,#fb4652 22%,transparent);--dm-py:#feba28;--dm-py-bg:color-mix(in srgb,#bb881a 22%,transparent);--dm-pk:#feabcf;--dm-pk-bg:color-mix(in srgb,#fb27a2 22%,transparent);--dm-pt:#19daeb;--dm-pt-bg:color-mix(in srgb,#1fa5b1 22%,transparent)}
/* the search and the plan filters: 16px in from the card's edges, the last filter ending on the content's right edge. The
   field's glass sits in the logos' column and its words start on the names' column, as the rows under it do */
.dm-atb-h{display:flex;align-items:center;gap:var(--dm-s-2);padding:var(--dm-s-4) var(--dm-s-4) var(--dm-s-3);flex-wrap:wrap;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
/* a narrow card (a phone): the search takes the width and the filters go under it, on its left edge */
.dm-atb{container-type:inline-size}
@container (max-width:420px){.dm-atb-h{flex-direction:column;align-items:stretch}.dm-atb-h>.dm-atb-s{flex:none;min-width:0}}
.dm-atb-s{display:flex;align-items:center;gap:var(--dm-s-4);height:32px;padding:0 10px 0 6px;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);color:var(--dm-muted);flex:1;min-width:160px;transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.dm-atb-s{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.dm-atb-s input{flex:1;min-width:0;height:100%;border:0;outline:0;background:transparent;font:inherit;font-size:13px;color:var(--dm-fg)}
.dm-atb-s:has(input:focus){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.dm-atb-s input::placeholder{color:var(--dm-muted)}
.dm-atb-fl{display:flex;gap:var(--dm-s-1);flex-wrap:wrap}
/* the filters are white chips with a dimmed grey edge; the picked one's edge is a step stronger */
.dm-atb-fl .dm-chip{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-line) 50%,transparent)}
@media (hover:hover) and (pointer:fine){.dm-atb-fl .dm-chip:hover{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-faint) 50%,transparent)}}
/* the table sits 8px in from the card's sides, and its first and last cells keep 8px more: every column's words start where
   its head's words start, the first 16px in and the last ending 16px from the right, and a row's hover fill reaches 8px out
   round them with rounded corners, in place of the hairlines round it (owner, 18 Nov). On a phone the table scrolls sideways */
/* the rows' fills reach as far toward the foot as toward the sides: 8px */
.dm-atb-sc{overflow-x:auto;padding:0 var(--dm-s-2) var(--dm-s-2)}
.dm-atb table{width:100%;border-collapse:separate;border-spacing:0;font-size:13px;min-width:560px}
.dm-atb th{text-align:left;font-weight:500;font-size:12px;line-height:18px;color:var(--dm-muted);padding:10px var(--dm-s-3);white-space:nowrap}
.dm-atb th.dm-r,.dm-atb td.dm-r{text-align:right}
/* it reads as a table of columns (owner, 10 and 21 Nov): a hairline after every column but the last, in every style and
   wherever the columns have been moved; the note under a row spans them all with none. The columns resize and move as in a
   spreadsheet (cols()): a header takes the keyboard's focus so Alt and an arrow can move it, and sized by hand, a cell too
   narrow for its words cuts them short */
.dm-atb{--dm-atb-col:color-mix(in srgb,color-mix(in srgb,var(--dm-line),var(--dm-fg) 9%) 50%,transparent)}
.dm-atb :is(th,td):not(:last-child){box-shadow:inset -1px 0 0 var(--dm-atb-col)}
.dm-atb th{position:relative}
.dm-atb th[tabindex]:focus-visible{outline-offset:-2px;border-radius:var(--dm-r-xs)}
.dm-atb table.dm-cols-rz td{overflow:hidden;text-overflow:ellipsis}
.dm-atb td{padding:10px var(--dm-s-3);line-height:20px;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);white-space:nowrap;transition:background-color var(--dm-t-fast) var(--dm-ease)}
.dm-atb :is(th,td):first-child{padding-left:var(--dm-s-2)}
.dm-atb :is(th,td):last-child{padding-right:var(--dm-s-2)}
.dm-atb tr.dm-row{cursor:pointer}
@media (hover:hover) and (pointer:fine){
  .dm-atb tr.dm-row:hover td{background:color-mix(in srgb,var(--dm-fg) 4%,transparent);border-top-color:transparent}
  .dm-atb tr.dm-row:hover td:first-child{border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk))) 0 0 calc(8px * var(--dm-rk-m,var(--dm-rk)))}
  .dm-atb tr.dm-row:hover td:last-child{border-radius:0 calc(8px * var(--dm-rk-m,var(--dm-rk))) calc(8px * var(--dm-rk-m,var(--dm-rk))) 0}
  .dm-atb tr.dm-row:hover+tr td{border-top-color:transparent}
}
/* a row that takes the focus fills the scrolling table, which would cut an outside ring: its ring is drawn inside */
.dm-atb tr.dm-row:focus-visible{outline-offset:-2px}
.dm-atb .dm-nm{display:flex;align-items:center;gap:10px;font-weight:500}
/* brand tiles sit a shade darker than the brand colour, so their white letter reads at 4.5:1 or more */
.dm-atb .dm-lg{width:24px;height:24px;border-radius:calc(7px * var(--dm-rk-m,var(--dm-rk)));display:grid;place-items:center;font-size:10px;font-weight:500;color:#fff}
.dm-atb .dm-hb{display:flex;align-items:center;gap:var(--dm-s-2)}
.dm-atb .dm-hb i{width:54px;height:5px;border-radius:var(--dm-r-tiny,3px);background:var(--dm-line);overflow:hidden;display:block}
.dm-atb .dm-hb i b{display:block;height:100%;border-radius:var(--dm-r-tiny,3px)}
.dm-atb .dm-hb span{font-size:12px;color:var(--dm-fg2)}
/* the agent's note opens under its row, with no hairline between them: the spark centred under the logos, the words on the
   names' column, and its button ending where MRR ends, centred on the words */
.dm-atb tr.dm-det td{padding:0;border-top:0}
/* the note is a detail row under its account (owner, 21 Nov): it spans every column, so the column lines stop at its top edge and
   start again under it, and it sits in an inset panel of the style's quiet fill (Clean: its off-white with 10px corners), its
   spark under the logos and its words on the names' column; the account it belongs to keeps a quiet fill while it is open */
.dm-atb-note{display:flex;align-items:center;gap:var(--dm-s-3);margin:0 0 var(--dm-s-2);padding:10px var(--dm-s-2) 10px 14px;border-radius:var(--dm-r-in);background:var(--dm-wash);font-size:12.5px;line-height:1.5;color:var(--dm-fg2);white-space:normal}
.dm-atb-note>svg{color:var(--dm-accent-mark,var(--dm-accent));flex:none;margin-right:4px}
.dm-atb-note span{flex:1}
/* Draft email is as wide as its words, and eases to the new width as it says Drafting, then Draft ready with the green tick */
.dm-atb-note .dm-pill{flex:none;overflow:hidden}
/* a white button on a tinted row takes the tint hairline (CLAUDE.md); Blueprint keeps its outlined edge */
.dm-atb-note .dm-pill.dm-line{box-shadow:var(--dm-on-tint-btn)}
@media (hover:hover) and (pointer:fine){.dm-atb-note .dm-pill.dm-line:hover{box-shadow:var(--dm-on-tint-btn-h)}}
:root:not([data-style="soft"],[data-style="clean"]) .dm-atb-note .dm-pill.dm-line:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-atb-note .dm-pill .dm-spin{width:12px;height:12px}
.dm-atb-note .dm-pill .dm-atb-done{display:grid;color:var(--dm-ok-mark)}
/* nothing matches: the empty state of the lab's Clean (lab/clean), in every style. A small sketch of a table on a white card,
   what happened, one muted line and the way back to every account */
.dm-atb-empty td{padding:28px var(--dm-s-4) 30px;text-align:center;white-space:normal}
.dm-atb-em{display:flex;flex-direction:column;align-items:center;gap:4px}
.dm-atb-em b{font-size:13.5px;line-height:18px;font-weight:500;color:var(--dm-fg)}
.dm-atb-em>span:not(.dm-atb-em-art){max-width:290px;font-size:12.5px;line-height:1.5;color:var(--dm-muted)}
.dm-atb-em .dm-pill{margin-top:12px}
.dm-atb-em-art{position:relative;display:block;width:136px;height:70px;margin:0 0 16px;border-radius:calc(10px * var(--dm-rk-l,var(--dm-rk)));background:var(--dm-surface);box-shadow:var(--dm-shadow)}
.dm-atb-em-art::before{content:"";position:absolute;left:14px;top:14px;width:10px;height:10px;border-radius:3px;background:var(--dm-ghost,var(--dm-chip));box-shadow:0 16px 0 var(--dm-ghost,var(--dm-chip)),0 32px 0 var(--dm-ghost-2,color-mix(in srgb,var(--dm-chip) 60%,var(--dm-surface)))}
.dm-atb-em-art::after{content:"";position:absolute;left:32px;top:16px;width:58px;height:6px;border-radius:3px;background:var(--dm-ghost,var(--dm-chip));box-shadow:0 16px 0 var(--dm-ghost,var(--dm-chip)),0 32px 0 var(--dm-ghost-2,color-mix(in srgb,var(--dm-chip) 60%,var(--dm-surface)))}
/* Clean: the same 16px insets, the spark the quiet grey of Clean's chrome */
:root[data-style="clean"] .dm-atb-note>svg,:root [data-style="clean"] .dm-atb-note>svg,:root [data-style="clean"].dm-atb-note>svg{color:var(--dm-fg2)}
:root[data-style="clean"] .dm-atb-note,:root [data-style="clean"] .dm-atb-note,:root [data-style="clean"].dm-atb-note{border-radius:10px;background:var(--dm-strip);box-shadow:inset 0 0 0 1px var(--dm-hair)}
.dm-atb tr.dm-row.dm-open td{background:var(--dm-row);border-top-color:transparent}
.dm-atb tr.dm-row.dm-open td:first-child{border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk))) 0 0 calc(8px * var(--dm-rk-m,var(--dm-rk)))}
.dm-atb tr.dm-row.dm-open td:last-child{border-radius:0 calc(8px * var(--dm-rk-m,var(--dm-rk))) calc(8px * var(--dm-rk-m,var(--dm-rk))) 0}
/* Clean: the search and the plan filters sit in the card's off-white head strip, with a hairline under it (owner, 21 Nov: "add
   a gray background behind the search accounts"), 16px in at the sides and 16px from its top and bottom (owner, 23 Nov) */
:root[data-style="clean"] .dm-atb-h,:root [data-style="clean"] .dm-atb-h,:root [data-style="clean"].dm-atb-h{padding:var(--dm-strip-y) 16px;background:var(--dm-strip);border-bottom:1px solid var(--dm-line);border-radius:var(--dm-r-card) var(--dm-r-card) 0 0}
/* the filter chips keep their quiet edge: the one hover fills them, and the picked one has the stronger fill (owner, 21 Nov) */
:root[data-style="clean"] .dm-atb-fl .dm-chip,:root [data-style="clean"] .dm-atb-fl .dm-chip,:root [data-style="clean"].dm-atb-fl .dm-chip{transition:background-color var(--dm-t-fast) var(--dm-ease),box-shadow var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dm-atb-fl .dm-chip:not(.dm-on):hover,:root [data-style="clean"] .dm-atb-fl .dm-chip:not(.dm-on):hover,:root [data-style="clean"].dm-atb-fl .dm-chip:not(.dm-on):hover{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-line) 50%,transparent),inset 0 0 0 99px var(--dm-row)}}
:root[data-style="clean"] .dm-atb-fl .dm-chip.dm-on,:root [data-style="clean"] .dm-atb-fl .dm-chip.dm-on,:root [data-style="clean"].dm-atb-fl .dm-chip.dm-on{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-line) 50%,transparent),inset 0 0 0 99px var(--dm-row-on)}
